package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number expected = 123;
        assertEquals(expected, NumberUtils.createNumber("123"));
    }

    @Test
    public void testCreateNumber_Long() {
        // A number that fits in Long but not Integer
        String val = "3000000000"; 
        Number result = NumberUtils.createNumber(val);
        assertTrue(result instanceof Long);
        assertEquals(3000000000L, result.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String val = "99999999999999999999999999999999999999";
        Number result = NumberUtils.createNumber(val);
        assertTrue(result instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_HexInt() {
        Number result = NumberUtils.createNumber("0x123");
        assertTrue(result instanceof Integer);
        assertEquals(0x123, result.intValue());
    }

    @Test
    public void testCreateNumber_HexLong() {
        // Hex length > 8 digits (excluding 0x)
        Number result = NumberUtils.createNumber("0x123456789");
        assertTrue(result instanceof Long);
    }

    @Test
    public void testCreateNumber_NegativeHexInt() {
        Number result = NumberUtils.createNumber("-0x123");
        assertTrue(result instanceof Integer);
        assertEquals(-0x123, result.intValue());
    }

    @Test
    public void testCreateNumber_NegativeHexLong() {
        Number result = NumberUtils.createNumber("-0x123456789");
        assertTrue(result instanceof Long);
    }

    @Test
    public void testCreateNumber_FloatSuffix() {
        Number result = NumberUtils.createNumber("123.45f");
        assertTrue(result instanceof Float);
        assertEquals(123.45f, result.floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_DoubleSuffix() {
        Number result = NumberUtils.createNumber("123.45d");
        assertTrue(result instanceof Double);
        assertEquals(123.45, result.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_LongSuffix() {
        Number result = NumberUtils.createNumber("123L");
        assertTrue(result instanceof Long);
        assertEquals(123L, result.longValue());
    }

    @Test
    public void testCreateNumber_BigIntegerSuffix() {
        // Very large number with L suffix to trigger BigInteger
        String val = "99999999999999999999999999999999999999L";
        Number result = NumberUtils.createNumber(val);
        assertTrue(result instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Decimal() {
        Number result = NumberUtils.createNumber("123.456");
        // Should try Float, then Double, then BigDecimal. 
        // Usually returns Double or BigDecimal depending on precision
        assertTrue(result instanceof Double || result instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_ScientificNotation() {
        Number result = NumberUtils.createNumber("1.23e2");
        assertEquals(123.0, result.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_ScientificNotationWithSuffix() {
        Number result = NumberUtils.createNumber("1.23e2f");
        assertTrue(result instanceof Float);
        assertEquals(123.0f, result.floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        // 'z' is not a valid suffix
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("123z"));
    }

    @Test
    public void testCreateNumber_InvalidFormat_ExpTooLarge() {
        // Testing the logic: if (expPos > str.length())
        // Note: The logic in the provided code for expPos calculation is a bit unusual:
        // int expPos = str.indexOf('e') + str.indexOf('E') - 1;
        // If 'e' is at index 4 and 'E' is at index -1, expPos = 4 - 1 - 1 = 2.
        // If 'e' is at index 4 and 'E' is at index 4, expPos = 4 + 4 - 1 = 7.
        // This might cause unexpected behavior, but we test the branch.
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1.2.3"));
    }

    @Test
    public void testCreateNumber_AllZeros_FloatCheck() {
        // Test the logic: if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)))
        // This ensures that "0.000" is handled correctly as a zero.
        Number result = NumberUtils.createNumber("0.000f");
        assertEquals(0.0f, result.floatValue(), 0.0f);
    }

    @Test
    public void testCreateNumber_InvalidDecimalExp() {
        // Testing case where expPos is invalid relative to decPos
        // This depends on how the specific math of the provided code calculates expPos
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1e2.5"));
    }

    @Test
    public void testCreateNumber_LargeLongSuffixFallback() {
        // Test the try-catch block where createLong fails and it returns BigInteger
        String val = "9223372036854775808L"; // Long.MAX_VALUE + 1
        Number result = NumberUtils.createNumber(val);
        assertTrue(result instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_BigDecimalFallback() {
        // Test the case where Double/Float fails or is infinite, falling back to BigDecimal
        // Using a very large number that might be infinite in float/double
        String val = "1e1000"; 
        Number result = NumberUtils.createNumber(val);
        // Depending on implementation, it might return Double.POSITIVE_INFINITY or BigDecimal
        assertNotNull(result);
    }

    /**
     * Helper to assert exception in JUnit 4
     */
    private static <T extends Throwable> void assertThrows(Class<T> expectedType, Runnable runnable) {
        try {
            runnable.run();
            fail("Expected exception " + expectedType.getName() + " but none was thrown.");
        } catch (Throwable t) {
            if (expectedType.isInstance(t)) {
                return;
            } else {
                fail("Expected exception " + expectedType.getName() + " but caught " + t.getClass().getName());
            }
        }
    }
}
